#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cwchar>
#include <initializer_list>

int main() {
    char first[64];
    char second[64];
    if (std::scanf("%63s %63s", first, second) != 2) return 1;
    if (std::strlen(first) < 1 || std::strlen(first) > 50) return 1;
    if (std::strlen(second) < 1 || std::strlen(second) > 50) return 1;
    for (const char* word : {first, second}) {
        for (const char* p = word; *p != '\0'; p++) {
            if (*p < 'a' || *p > 'z') return 1;
        }
    }
    wchar_t wide_first[64];
    wchar_t wide_second[64];
    if (std::mbstowcs(wide_first, first, 64) == static_cast<std::size_t>(-1)) return 1;
    if (std::mbstowcs(wide_second, second, 64) == static_cast<std::size_t>(-1)) return 1;
    int order = std::wcscmp(wide_first, wide_second);
    if (order < 0) {
        std::printf("%s\n", first);
    } else if (order > 0) {
        std::printf("%s\n", second);
    } else {
        std::printf("equal\n");
    }
    return 0;
}
